<script setup lang="ts">
const email=ref(''),loading=ref(false),sent=ref(false),error=ref('');async function submit(){loading.value=true;error.value='';try{await $fetch('/api/auth/forgot-password',{method:'POST',body:{email:email.value}});sent.value=true}catch(e:any){error.value=e?.data?.statusMessage||'Envoi impossible'}finally{loading.value=false}};useSeoMeta({title:'Mot de passe oublié'})
</script><template><main class="auth-page page-top"><section class="auth-card"><p class="eyebrow">RÉCUPÉRATION</p><h1>Retrouvez votre compte.</h1><p v-if="!sent">Saisissez votre email. Le lien apparaîtra dans Mailpit en environnement local.</p><div v-if="sent" class="auth-success"><AppIcon name="check"/><strong>Email envoyé</strong><p>Consultez votre boîte ou Mailpit sur le port 8025.</p></div><form v-else @submit.prevent="submit"><label>Email<input v-model="email" type="email" required></label><p v-if="error" class="auth-error">{{ error }}</p><button class="btn btn--primary" :disabled="loading">{{ loading?'Envoi…':'Envoyer le lien' }}</button></form><p><NuxtLink to="/login">Retour à la connexion</NuxtLink></p></section></main></template>
